package com.campusmart.entity;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Order order;@ManyToOne(optional=false)private Product product;@Column(nullable=false)private int quantity;@Column(nullable=false,precision=12,scale=2)private BigDecimal unitPrice;public Long getId(){return id;}public Order getOrder(){return order;}public void setOrder(Order v){order=v;}public Product getProduct(){return product;}public void setProduct(Product v){product=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}public BigDecimal getUnitPrice(){return unitPrice;}public void setUnitPrice(BigDecimal v){unitPrice=v;}}
